text.main.ts:
// directions
game.setDialogFrame(assets.image`frameImage`)
game.setDialogCursor(assets.image`myImage`)
game.showLongText("Help me navigate between the two worlds!", DialogLayout.Full)

// project set up
scene.setBackgroundColor(13)
tiles.setCurrentTilemap(assets.tilemap`sunTilemap`)

// sprite set up
let mySprite = sprites.create(assets.image`myImage`, SpriteKind.Player)
mySprite.setScale(.7, ScaleAnchor.Middle)
tiles.placeOnTile(mySprite, tiles.getTileLocation(8, 3))
controller.moveSprite(mySprite)

// tilemap overlap events
scene.onOverlapTile(SpriteKind.Player, img` `, function (sprite: Sprite, location: tiles.Location) {
    tiles.setCurrentTilemap(assets.tilemap`treeTilemap`)
    scene.setBackgroundColor(7)
})

scene.onOverlapTile(SpriteKind.Player, assets.tile`sunTile`, function (sprite: Sprite, location: tiles.Location) {
    tiles.setCurrentTilemap(assets.tilemap`treeTilemap`)
    scene.setBackgroundColor(13)
})

